// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// DpiaScreenActivity Answer the DPIA screening form for a RoPA processing activity (DPIA-01): the system computes required / recommended / not_required against the tenant's own thresholds (DPIA-02)
	// (POST /admin/v1/dpia/activities/{id}/screen)
	DpiaScreenActivity(ctx context.Context, request DpiaScreenActivityRequestObject) (DpiaScreenActivityResponseObject, error)
	// DpiaListAssessments The tenant's DPIA screening rounds, newest first
	// (GET /admin/v1/dpia/assessments)
	DpiaListAssessments(ctx context.Context, request DpiaListAssessmentsRequestObject) (DpiaListAssessmentsResponseObject, error)
	// DpiaGetAssessment One DPIA screening round with its factor answers
	// (GET /admin/v1/dpia/assessments/{id})
	DpiaGetAssessment(ctx context.Context, request DpiaGetAssessmentRequestObject) (DpiaGetAssessmentResponseObject, error)
	// DpiaGetAssessmentDescription DPIA-04: the assessment's processing description, composed live from its RoPA activity
	// (GET /admin/v1/dpia/assessments/{id}/description)
	DpiaGetAssessmentDescription(ctx context.Context, request DpiaGetAssessmentDescriptionRequestObject) (DpiaGetAssessmentDescriptionResponseObject, error)
	// DpiaGetAssessmentDiff DPIA-14: which screening answers changed since the previous round
	// (GET /admin/v1/dpia/assessments/{id}/diff)
	DpiaGetAssessmentDiff(ctx context.Context, request DpiaGetAssessmentDiffRequestObject) (DpiaGetAssessmentDiffResponseObject, error)
	// DpiaGetNecessity DPIA-05: the assessment's necessity/proportionality checklist and its conclusion
	// (GET /admin/v1/dpia/assessments/{id}/necessity)
	DpiaGetNecessity(ctx context.Context, request DpiaGetNecessityRequestObject) (DpiaGetNecessityResponseObject, error)
	// DpiaAssessNecessity DPIA-05: answer (or re-answer) the necessity/proportionality checklist — ม.22 data minimization, ม.24/26 lawful basis fit, a less invasive alternative considered
	// (POST /admin/v1/dpia/assessments/{id}/necessity)
	DpiaAssessNecessity(ctx context.Context, request DpiaAssessNecessityRequestObject) (DpiaAssessNecessityResponseObject, error)
	// DpiaListOpinions DPIA-10: every DPO opinion recorded against this assessment round, oldest first
	// (GET /admin/v1/dpia/assessments/{id}/opinions)
	DpiaListOpinions(ctx context.Context, request DpiaListOpinionsRequestObject) (DpiaListOpinionsResponseObject, error)
	// DpiaRecordOpinion DPIA-10: the DPO's written opinion and recommendation on a round under review
	// (POST /admin/v1/dpia/assessments/{id}/opinions)
	DpiaRecordOpinion(ctx context.Context, request DpiaRecordOpinionRequestObject) (DpiaRecordOpinionResponseObject, error)
	// DpiaGetReport DPIA-15: render the assessment as a PDF or Word report, TH or EN — score, linked security measures and DPO opinions/approvers
	// (GET /admin/v1/dpia/assessments/{id}/report)
	DpiaGetReport(ctx context.Context, request DpiaGetReportRequestObject) (DpiaGetReportResponseObject, error)
	// DpiaListAssessmentRisks DPIA-06: every risk identified against this assessment round
	// (GET /admin/v1/dpia/assessments/{id}/risks)
	DpiaListAssessmentRisks(ctx context.Context, request DpiaListAssessmentRisksRequestObject) (DpiaListAssessmentRisksResponseObject, error)
	// DpiaIdentifyRisk DPIA-06: identify and score a risk (likelihood x impact against the tenant's own matrix, RRA-02)
	// (POST /admin/v1/dpia/assessments/{id}/risks)
	DpiaIdentifyRisk(ctx context.Context, request DpiaIdentifyRiskRequestObject) (DpiaIdentifyRiskResponseObject, error)
	// DpiaRemoveAssessmentRisk DPIA-06: unlink a risk from this assessment round (the risk.risks row itself is kept)
	// (DELETE /admin/v1/dpia/assessments/{id}/risks/{riskId})
	DpiaRemoveAssessmentRisk(ctx context.Context, request DpiaRemoveAssessmentRiskRequestObject) (DpiaRemoveAssessmentRiskResponseObject, error)
	// DpiaUpdateRisk DPIA-06: edit a risk already identified against this assessment round
	// (PUT /admin/v1/dpia/assessments/{id}/risks/{riskId})
	DpiaUpdateRisk(ctx context.Context, request DpiaUpdateRiskRequestObject) (DpiaUpdateRiskResponseObject, error)
	// DpiaListRiskControls DPIA-07: every mitigation measure linked to this risk
	// (GET /admin/v1/dpia/assessments/{id}/risks/{riskId}/controls)
	DpiaListRiskControls(ctx context.Context, request DpiaListRiskControlsRequestObject) (DpiaListRiskControlsResponseObject, error)
	// DpiaAddRiskControl DPIA-07: link a mitigation measure from the ม.37(1) catalog; owner + due date opens a tracked task
	// (POST /admin/v1/dpia/assessments/{id}/risks/{riskId}/controls)
	DpiaAddRiskControl(ctx context.Context, request DpiaAddRiskControlRequestObject) (DpiaAddRiskControlResponseObject, error)
	// DpiaRemoveRiskControl DPIA-07: unlink a mitigation measure; the risk's residual score is recomputed
	// (DELETE /admin/v1/dpia/assessments/{id}/risks/{riskId}/controls/{controlId})
	DpiaRemoveRiskControl(ctx context.Context, request DpiaRemoveRiskControlRequestObject) (DpiaRemoveRiskControlResponseObject, error)
	// DpiaUpdateRiskControlStatus DPIA-07: change a linked control's own status (e.g. planned -> implemented)
	// (PUT /admin/v1/dpia/assessments/{id}/risks/{riskId}/controls/{controlId})
	DpiaUpdateRiskControlStatus(ctx context.Context, request DpiaUpdateRiskControlStatusRequestObject) (DpiaUpdateRiskControlStatusResponseObject, error)
	// DpiaTransitionAssessment DPIA-10: submit for review, request more info, decide (approved/rejected/needs_review), resume or close (ST-05#2) — deciding or closing needs assessment.dpia.approve beyond the endpoint's own permission
	// (POST /admin/v1/dpia/assessments/{id}/transition)
	DpiaTransitionAssessment(ctx context.Context, request DpiaTransitionAssessmentRequestObject) (DpiaTransitionAssessmentResponseObject, error)
	// DpiaGetRegistry DPIA-12: every RoPA activity's current DPIA round in one report, read live so its status always matches reality (no pagination, same precedent as ROPA-04's own processor-RoPA export)
	// (GET /admin/v1/dpia/registry)
	DpiaGetRegistry(ctx context.Context, request DpiaGetRegistryRequestObject) (DpiaGetRegistryResponseObject, error)
	// DpiaRiskCatalog DPIA-06: the ready-made risk catalog used to prefill the "add risk" form
	// (GET /admin/v1/dpia/risk-catalog)
	DpiaRiskCatalog(ctx context.Context, request DpiaRiskCatalogRequestObject) (DpiaRiskCatalogResponseObject, error)
	// DpiaGetScreeningRules The tenant's DPIA-02 screening thresholds (defaults if none saved yet)
	// (GET /admin/v1/dpia/screening-rules)
	DpiaGetScreeningRules(ctx context.Context, request DpiaGetScreeningRulesRequestObject) (DpiaGetScreeningRulesResponseObject, error)
	// DpiaSaveScreeningRules Set the DPIA-02 thresholds a screening result is judged against (takes effect on the next screening round)
	// (PUT /admin/v1/dpia/screening-rules)
	DpiaSaveScreeningRules(ctx context.Context, request DpiaSaveScreeningRulesRequestObject) (DpiaSaveScreeningRulesResponseObject, error)
	// DpiaListTemplates The template library (DPIA-03): global defaults + the tenant's own, optionally by assessment_type
	// (GET /admin/v1/dpia/templates)
	DpiaListTemplates(ctx context.Context, request DpiaListTemplatesRequestObject) (DpiaListTemplatesResponseObject, error)
	// DpiaCreateTemplate Author a brand-new assessment template (its own PLT-06 form, draft)
	// (POST /admin/v1/dpia/templates)
	DpiaCreateTemplate(ctx context.Context, request DpiaCreateTemplateRequestObject) (DpiaCreateTemplateResponseObject, error)
	// DpiaGetTemplate One template
	// (GET /admin/v1/dpia/templates/{id})
	DpiaGetTemplate(ctx context.Context, request DpiaGetTemplateRequestObject) (DpiaGetTemplateResponseObject, error)
	// DpiaCloneTemplate Clone a template (DPIA-03): a fully independent copy of its current content — editing the clone never affects the original
	// (POST /admin/v1/dpia/templates/{id}/clone)
	DpiaCloneTemplate(ctx context.Context, request DpiaCloneTemplateRequestObject) (DpiaCloneTemplateResponseObject, error)
	// DpiaPublishTemplate Publish the template's current draft (If-Match = the form's own ETag) and mark the template live
	// (POST /admin/v1/dpia/templates/{id}/publish)
	DpiaPublishTemplate(ctx context.Context, request DpiaPublishTemplateRequestObject) (DpiaPublishTemplateResponseObject, error)
	// DpiaRetireTemplate Withdraw a template from use (If-Match = the template's own ETag)
	// (POST /admin/v1/dpia/templates/{id}/retire)
	DpiaRetireTemplate(ctx context.Context, request DpiaRetireTemplateRequestObject) (DpiaRetireTemplateResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// DpiaScreenActivity operation middleware
func (sh *strictHandler) DpiaScreenActivity(w http.ResponseWriter, r *http.Request, id Uuid, params DpiaScreenActivityParams) {
	var request DpiaScreenActivityRequestObject

	request.Id = id
	request.Params = params

	var body DpiaScreenActivityJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.DpiaScreenActivity(ctx, request.(DpiaScreenActivityRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "DpiaScreenActivity")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(DpiaScreenActivityResponseObject); ok {
		if err := validResponse.VisitDpiaScreenActivityResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

